          hiddenInfoParagraph3: 'তাঁর পছন্দ যেকোনো সময় বদলাতে পারে। AWA Together আপনাকে শুধু সেই তথ্যই দেখায়, যা এখন আপনি দেখার অনুমতি পেয়েছেন।',
